import{_ as u,B as n,o as t,c as g,a8 as r,d as m,w as l,f as c,E as o,af as h,a}from"./chunks/framework.CNIpabDg.js";const _=JSON.parse('{"title":"Log","description":"The Log module is the global bridge between Xila logging calls and a concrete backend implementation.","frontmatter":{"layout":"doc","docType":"explanation","description":"The Log module is the global bridge between Xila logging calls and a concrete backend implementation."},"headers":[],"relativePath":"explanation/architecture/subsystems/log.md","filePath":"explanation/architecture/subsystems/log.md","lastUpdated":1792485373000}'),p={name:"explanation/architecture/subsystems/log.md"};function b(f,e,k,y,v,x){const d=n("Mermaid"),s=n("CodeReference"),i=n("HostReference");return t(),g("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792485373000"},[e[3]||(e[3]=r('<h1 id="log" tabindex="-1">Log <a class="header-anchor" href="#log" aria-label="Permalink to &quot;Log&quot;">​</a></h1><p>The Log module is the global bridge between Xila logging calls and a concrete backend implementation.</p><h2 id="role-in-system" tabindex="-1">Role in system <a class="header-anchor" href="#role-in-system" aria-label="Permalink to &quot;Role in system&quot;">​</a></h2><ul><li>Provides uniform log macros (<code>error!</code>, <code>warning!</code>, <code>information!</code>, <code>debug!</code>, <code>trace!</code>) across modules.</li><li>Adapts Xila-specific <code>LoggerTrait</code> to the external <code>log</code> crate runtime.</li><li>Centralizes level filtering and formatted record emission policy.</li></ul><h2 id="responsibilities-and-boundaries" tabindex="-1">Responsibilities and boundaries <a class="header-anchor" href="#responsibilities-and-boundaries" aria-label="Permalink to &quot;Responsibilities and boundaries&quot;">​</a></h2><p><strong>In scope</strong></p><ul><li>Global logger initialization and registration.</li><li>Severity-level mapping and default formatting.</li><li>Backend trait abstraction (<code>enabled</code>, <code>write</code>, optional <code>flush</code>).</li></ul><p><strong>Out of scope</strong></p><ul><li>Transport/storage mechanics (console, serial, file, remote).</li><li>Advanced aggregation/query infrastructure.</li></ul><h2 id="internal-architecture" tabindex="-1">Internal architecture <a class="header-anchor" href="#internal-architecture" aria-label="Permalink to &quot;Internal architecture&quot;">​</a></h2><ul><li><code>LOGGER_INSTANCE: OnceLock&lt;Logger&gt;</code> stores single logger adapter.</li><li><code>LoggerTrait</code> is backend contract; <code>Logger</code> adapter implements <code>log_external::Log</code>.</li><li><code>Record</code> structure captures normalized level/target/arguments.</li><li>Default <code>LoggerTrait::log</code> formatting decorates lines with level tag and ANSI color tokens.</li></ul><p><strong>Contract vs implementation</strong></p><ul><li><strong>Contract</strong>: backend <code>LoggerTrait</code> methods and macro-level behavior.</li><li><strong>Implementation</strong>: concrete formatting/color tokens and <code>set_max_level</code> policy.</li></ul>',13)),(t(),m(h,null,{default:l(()=>[o(d,{id:"mermaid-104",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Clients%40%7B%20shape%3A%20processes%2C%20label%3A%20%22Modules%20%2F%20executables%22%20%7D%0A%20%20%20%20Macros%5Berror!%2Fwarning!%2Finformation!%2Fdebug!%2Ftrace!%5D%0A%20%20%20%20Bridge%5Blog%20module%20bridge%5D%0A%20%20%20%20Once%5BLOGGER_INSTANCE%20OnceLock%5D%0A%20%20%20%20Backend%5BLoggerTrait%20backend%5D%0A%0A%20%20%20%20Clients%20--%3E%20Macros%0A%20%20%20%20Macros%20--%3E%20Bridge%0A%20%20%20%20Bridge%20--%3E%20Once%0A%20%20%20%20Once%20--%3E%20Backend%0A%20%20%20%20Backend%20--%3E%7Cwrite%2Fflush%7C%20Output%5BConsole%20%2F%20file%20%2F%20platform%20sink%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<h2 id="lifecycle-and-execution-model" tabindex="-1">Lifecycle and execution model <a class="header-anchor" href="#lifecycle-and-execution-model" aria-label="Permalink to &quot;Lifecycle and execution model&quot;">​</a></h2><ol><li>Platform creates backend implementing <code>LoggerTrait</code>.</li><li>Runtime calls <code>log::initialize(...)</code> once.</li><li>Module macros emit through <code>log</code> ecosystem into adapter and backend sink.</li></ol><h2 id="data-control-flow" tabindex="-1">Data/control flow <a class="header-anchor" href="#data-control-flow" aria-label="Permalink to &quot;Data/control flow&quot;">​</a></h2><ul><li>Macro invocation -&gt; <code>log_external</code> -&gt; <code>Logger</code> adapter -&gt; <code>LoggerTrait::enabled/log/write</code>.</li><li>Initialization attempts after first registration do not replace logger; they emit an error log.</li></ul><h2 id="concurrency-and-synchronization-model" tabindex="-1">Concurrency and synchronization model <a class="header-anchor" href="#concurrency-and-synchronization-model" aria-label="Permalink to &quot;Concurrency and synchronization model&quot;">​</a></h2><ul><li>Singleton registration guarded by <code>OnceLock</code>.</li><li>Thread-safety at runtime relies on backend <code>LoggerTrait: Send + Sync</code> and backend internals.</li></ul><h2 id="dependency-model" tabindex="-1">Dependency model <a class="header-anchor" href="#dependency-model" aria-label="Permalink to &quot;Dependency model&quot;">​</a></h2><ul><li>Depends on <code>log</code> ecosystem crate for macro/runtime integration.</li><li>Consumed by nearly all core modules for diagnostics.</li></ul><h2 id="failure-semantics-and-recovery-behavior" tabindex="-1">Failure semantics and recovery behavior <a class="header-anchor" href="#failure-semantics-and-recovery-behavior" aria-label="Permalink to &quot;Failure semantics and recovery behavior&quot;">​</a></h2><ul><li><code>initialize</code> returns <code>Ok(())</code> even if logger was already set in <code>log</code> runtime; duplicate init is reported via error record.</li><li>Backend write/flush behavior is backend-defined; module itself does not buffer/retry.</li></ul><h2 id="extension-points" tabindex="-1">Extension points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension points&quot;">​</a></h2><ul><li>Provide alternative backend implementations for each platform.</li><li>Override <code>LoggerTrait::log</code> for custom formatting or structured payload conventions.</li><li>Add runtime filtering policy in backend or wrapper layer.</li></ul><h2 id="known-limitations-and-trade-offs" tabindex="-1">Known limitations and trade-offs <a class="header-anchor" href="#known-limitations-and-trade-offs" aria-label="Permalink to &quot;Known limitations and trade-offs&quot;">​</a></h2><ul><li>Single global logger; dynamic replacement/reconfiguration is limited.</li><li>Formatting includes ANSI control sequences by default, which may be undesirable in non-terminal sinks unless backend adapts.</li><li>Reliability guarantees (buffering, durability) are sink-specific.</li></ul><h2 id="backend-contract-and-global-initialization" tabindex="-1">Backend contract and global initialization <a class="header-anchor" href="#backend-contract-and-global-initialization" aria-label="Permalink to &quot;Backend contract and global initialization&quot;">​</a></h2><p>A backend implements <code>LoggerTrait: Send + Sync</code>, supplying <code>enabled(Level)</code> and <code>write(fmt::Arguments)</code>. The default <code>log(Record)</code> method formats severity, target and arguments with ANSI escape sequences; <code>flush()</code> defaults to a no-op and may be overridden. <code>Level</code> covers Error, Warn, Info, Debug and Trace.</p><p><code>initialize(&amp;&#39;static dyn LoggerTrait)</code> stores a logger adapter in a <code>OnceLock</code> and registers it with the Rust <code>log</code> facade. This is process-global integration, unlike managers that can be freely instantiated. The facade maximum level is set to Trace, but the backend&#39;s <code>enabled()</code> still decides which records are emitted.</p><p><strong>Important initialization caveat:</strong> if <code>set_logger()</code> fails, the current implementation logs an error directly to the supplied backend and still returns <code>Ok(())</code>. Consequently a successful return does not prove that this backend became the active global logger. <code>is_initialized()</code> checks whether the internal <code>OnceLock</code> contains an adapter, not whether the requested backend was installed.</p><p>Applications can use the re-exported <code>error!</code>, <code>warning!</code>, <code>information!</code>, <code>debug!</code>, and <code>trace!</code> macros. Transport, persistence and concurrency behavior belong to the concrete backend, not the facade.</p><h3 id="implementation-references" tabindex="-1">Implementation references <a class="header-anchor" href="#implementation-references" aria-label="Permalink to &quot;Implementation references&quot;">​</a></h3>',20)),a("ul",null,[a("li",null,[o(s,{path:"subsystems/log/src/lib.rs"})]),a("li",null,[o(i,{crate:"log"})])]),e[5]||(e[5]=a("h2",{id:"references-see-also",tabindex:"-1"},[c("References / See also "),a("a",{class:"header-anchor",href:"#references-see-also","aria-label":'Permalink to "References / See also"'},"​")],-1)),a("ul",null,[a("li",null,[o(i,{crate:"log"})]),e[1]||(e[1]=a("li",null,[a("a",{href:"/explanation/architecture/drivers.html"},"Drivers")],-1)),e[2]||(e[2]=a("li",null,[a("a",{href:"/explanation/architecture/libraries/synchronization.html"},"Synchronization")],-1))])])}const L=u(p,[["render",b]]);export{_ as __pageData,L as default};
